						"query": "`corelight_idx` sensor_name=$tkn_sensor_name|s$  `corelight_evt_ssh`\n| mvexpand inferences\n| eval combo=mvzip(inferences, InferenceName, \"|\")\n| mvexpand combo\n| eval inference=mvindex(split(combo, \"|\"), 0), InferenceName=mvindex(split(combo, \"|\"), 1)\n| lookup ssh_inference inferences as inference OUTPUT Description\n| eval UseCase=case(\nmatch(inference, \"^(SC|SP|SV|SA|AFR|BAN)$\"), \"Potential Security Risks\"\n)\n| where isnotnull(UseCase)\n| table uid id.orig_h, id.resp_h, inference",
