						"query": "`corelight_idx` sensor_name=$tkn_sensor_name|s$  `corelight_evt_x509`\n| eval not_valid_after_epoch = strptime('certificate.not_valid_after', \"%Y-%m-%dT%H:%M:%S.000000Z\")\n| eval current_time_epoch = now()\n| eval days_to_expire = round((not_valid_after_epoch - current_time_epoch) / 86400, 0)\n| dedup fingerprint\n| where days_to_expire > 0 AND days_to_expire <= 15\n| rename ssl_subject_common_name as subject, 'certificate.not_valid_after' as cert_expiration_date\n| eval match_fingerprint=fingerprint\n| join type=inner match_fingerprint\n    [ search `corelight_idx` sensor_name=$tkn_sensor_name|s$  `corelight_evt_ssl` is_dest_internal_ip=\"true\"\n    | mvexpand cert_chain_fps{}\n    | rename cert_chain_fps{} as match_fingerprint\n    | fields match_fingerprint, uid, id.orig_h, id.resp_h, id.resp_p, is_dest_internal_ip, proto ]\n    | eval certificate.not_valid_after=strftime(strptime('certificate.not_valid_after', \"%Y-%m-%dT%H:%M:%S.000000Z\"), \"%B %d, %Y @ %H:%M\")\n| table subject, id.resp_h, id.resp_p, certificate.not_valid_after, days_to_expire\n| rename subject as Subject, id.resp_h as Host, certificate.not_valid_after as \"No Valid After\", days_to_expire as \"Days to Expire\"\n| sort - days_to_expire",
