						"query": "`corelight_idx` sensor_name=$tkn_sensor_name|s$  `corelight_evt_ssl` \n| where !match(cipher, \"RC4\") OR match(cipher, \"DES\") OR match(cipher, \"3DES\") OR match(cipher, \"MD5\") OR match(cipher, \"NULL\") OR match(cipher, \"EXPORT\")\n| join type=inner uid \n    [ search `corelight_idx` sensor_name=$tkn_sensor_name|s$  `corelight_evt_conn`\n    | fields uid, local_orig, local_resp, is_src_internal_ip ]\n| eval Direction=case(\n    local_orig=\"true\" AND local_resp=\"true\", \"Internal-Internal\",\n    local_orig=\"true\" AND local_resp=\"false\", \"Outbound\",\n    local_orig=\"false\" AND local_resp=\"true\", \"Inbound\"\n  )\n| eval Host_Type=if(is_src_internal_ip=\"true\", \"Internal\", \"External\")\n| stats dc(uid) as Unique_Conns, last(id.resp_h) as Hosts, count by cipher, Direction, Host_Type\n| sort -Unique_Conns",
						"type": "custom"
					},
					"type": "drilldown.linkToSearch"
